mapper.select:
select product_name as productName, product_no as productNo, product_type as productType, profit_amount as profitAmount, profit_rate as profitRate, status as status, create_time as createTime from w_profit_record where user_id = #{userId,jdbcType=VARCHAR}
and product_name like concat('%', #{productName,jdbcType=VARCHAR}, '%')
and product_no = #{productNo,jdbcType=VARCHAR}
and create_time >= #{startTime,jdbcType=VARCHAR}
and create_time <= #{endTime,jdbcType=VARCHAR}
order by create_time desc
